export async function upsert(records: StoreRecord[]): Promise<void> {
  await ensureCollection();
  await qdrant.upsert(COLLECTION, {
    wait: true,
    points: records.map(r => ({ id: pointId(r.id), vector: r.vector, payload: { chunkId: r.id, text: r.text, ...r.metadata } })),
  });
}

export async function search(vector: number[], k: number): Promise<SearchHit[]> {
  const hits = await qdrant.search(COLLECTION, { vector, limit: k, with_payload: true });
  return hits.map(h => ({ id: String(h.payload?.chunkId ?? h.id), text: String(h.payload?.text ?? ""), metadata: h.payload ?? {}, score: h.score }));
}

